class ExpressionEvaluator:
    def __init__(self, expr: str):
        self.expr = expr.replace(' ', '')
        self.pos = 0

    def parse(self) -> float:
        result = self._parse_expression()
        if self.pos < len(self.expr):
            raise ValueError("Unexpected characters at the end of expression")
        return result

    def _parse_expression(self) -> float:
        result = self._parse_term()
        while self.pos < len(self.expr):
            if self.expr[self.pos] == '+':
                self.pos += 1
                result += self._parse_term()
            elif self.expr[self.pos] == '-':
                self.pos += 1
                result -= self._parse_term()
            else:
                break
        return result

    def _parse_term(self) -> float:
        result = self._parse_factor()
        while self.pos < len(self.expr):
            if self.expr[self.pos] == '*':
                self.pos += 1
                result *= self._parse_factor()
            elif self.expr[self.pos] == '/':
                self.pos += 1
                divisor = self._parse_factor()
                if divisor == 0:
                    raise ZeroDivisionError("Division by zero")
                result /= divisor
            else:
                break
        return result

    def _parse_factor(self) -> float:
        if self.pos < len(self.expr) and self.expr[self.pos] == '(':
            self.pos += 1
            result = self._parse_expression()
            if self.pos < len(self.expr) and self.expr[self.pos] == ')':
                self.pos += 1
                return result
            else:
                raise ValueError("Mismatched parentheses")
        return self._parse_number()

    def _parse_number(self) -> float:
        start_pos = self.pos
        if self.pos < len(self.expr) and self.expr[self.pos] in '-+':
            self.pos += 1
        while self.pos < len(self.expr) and (self.expr[self.pos].isdigit() or self.expr[self.pos] == '.'):
            self.pos += 1
        number = self.expr[start_pos:self.pos]
        if not number:
            raise ValueError("Expected a number")
        return float(number)


