class ShuntingYard:
    def __init__(self, expr: str):
        self.expr = expr.replace(' ', '')
        self.output_queue = []
        self.operator_stack = []
        self.operators = {
            '+': (1, lambda x, y: x + y),
            '-': (1, lambda x, y: x - y),
            '*': (2, lambda x, y: x * y),
            '/': (2, lambda x, y: x / y)
        }

    def shunt(self):
        i = 0
        while i < len(self.expr):
            char = self.expr[i]
            if char.isdigit() or (char == '.' and (i > 0 and self.expr[i-1].isdigit())):
                number_start = i
                while (i < len(self.expr) and (self.expr[i].isdigit() or self.expr[i] == '.')):
                    i += 1
                self.output_queue.append(float(self.expr[number_start:i]))
                continue
            elif char in self.operators:
                while (self.operator_stack and self.operator_stack[-1] != '(' and 
                       self.operators[char][0] <= self.operators[self.operator_stack[-1]][0]):
                    self.output_queue.append(self.operator_stack.pop())
                self.operator_stack.append(char)
            elif char == '(':
                self.operator_stack.append(char)
            elif char == ')':
                while self.operator_stack and self.operator_stack[-1] != '(':
                    self.output_queue.append(self.operator_stack.pop())
                if not self.operator_stack or self.operator_stack[-1] != '(':
                    raise ValueError("Mismatched parentheses")
                self.operator_stack.pop()
            i += 1

        while self.operator_stack:
            self.output_queue.append(self.operator_stack.pop())

    def evaluate(self) -> float:
        stack = []
        for token in self.output_queue:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                stack.append(self.operators[token][1](a, b))
        return stack[0]

def evaluate(expr: str) -> float:
    """Evaluates an arithmetic expression using the Shunting Yard algorithm for parsing and evaluating."""
    evaluator = ShuntingYard(expr)
    evaluator.shunt()
    return evaluator.evaluate()

