                op = self.expr[self.pos]
                self.pos += 1
                value = self.apply_operator(value, self.parse_term(), op)
            else:
                break
        return value

    def parse_term(self) -> float:
        value = self.parse_factor()
        while self.pos < len(self.expr):
            if self.expr[self.pos] in ('*', '/'):
                op = self.expr[self.pos]
                self.pos += 1
                value = self.apply_operator(value, self.parse_factor(), op)
            else:
                break
        return value

    def parse_factor(self) -> float:
        if self.pos < len(self.expr):
            if self.expr[self.pos] == '(':
                self.pos += 1
                value = self.parse_expression()
                if self.expr[self.pos] != ')':
                    raise ValueError("Mismatched parentheses")
                self.pos += 1
                return value

            number_start = self.pos
            while (self.pos < len(self.expr) and 
                   (self.expr[self.pos].isdigit() or self.expr[self.pos] == '.')):
                self.pos += 1
            return float(self.expr[number_start:self.pos])

        raise ValueError("Invalid expression")

    def apply_operator(self, a: float, b: float, operator: str) -> float:
        if operator == '+':
            return a + b
        elif operator == '-':
            return a - b
        elif operator == '*':
            return a * b
        elif operator == '/':
            return a / b
        raise ValueError(f"Unknown operator: {operator}")

