    """Evaluates an arithmetic expression using the Shunting Yard algorithm to convert infix expressions to postfix notation, followed by evaluation."""

    def shunting_yard(expression):
        output = []
        operators = []
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

        i = 0
        while i < len(expression):
            token = expression[i]
            if token.isdigit() or (token == '.' and (i > 0 and expression[i - 1].isdigit())):
                num = token
                while (i + 1 < len(expression) and 
                       (expression[i + 1].isdigit() or expression[i + 1] == '.')):
                    i += 1
                    num += expression[i]
                output.append(float(num))
            elif token in precedence:
                while (operators and operators[-1] in precedence and
                       precedence[operators[-1]] >= precedence[token]):
                    output.append(operators.pop())
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    output.append(operators.pop())
                operators.pop()  # Remove '('
            i += 1

        while operators:
            output.append(operators.pop())

        return output

    def evaluate_postfix(postfix):
        stack = []
        for token in postfix:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        return stack[0]

    # Clean expression by removing whitespace
    expr = expr.replace(' ', '')
    postfix = shunting_yard(expr)
    return evaluate_postfix(postfix)

def evaluate(expr: str) -> float:
    """Evaluates an arithmetic expression using a recursive descent parser approach."""

    class Parser:
        def __init__(self, expression):
            self.tokens = self.tokenize(expression)
            self.pos = 0

        def tokenize(self, expr):
            tokens = []
            current_number = ''
            for char in expr:
                if char.isdigit() or char == '.':
                    current_number += char
                else:
                    if current_number:
                        tokens.append(float(current_number))
                        current_number = ''
                    if char in '+-*/()':
                        tokens.append(char)
            if current_number:
                tokens.append(float(current_number))
            return tokens

        def parse_expression(self):
            value = self.parse_term()
            while self.pos < len(self.tokens) and self.tokens[self.pos] in ('+', '-'):
                op = self.tokens[self.pos]
                self.pos += 1
                value = self.apply_operator(value, op, self.parse_term())
            return value

        def parse_term(self):
            value = self.parse_factor()
            while self.pos < len(self.tokens) and self.tokens[self.pos] in ('*', '/'):
                op = self.tokens[self.pos]
                self.pos += 1
                value = self.apply_operator(value, op, self.parse_factor())
            return value

        def parse_factor(self):
            if self.tokens[self.pos] == '(':
                self.pos += 1
                value = self.parse_expression()
                self.pos += 1  # skip ')'
                return value
            value = self.tokens[self.pos]
            self.pos += 1
            return value

        def apply_operator(self, left, operator, right):
            if operator == '+':
                return left + right
            elif operator == '-':
                return left - right
            elif operator == '*':
                return left * right
            elif operator == '/':
                return left / right

    parser = Parser(expr.replace(' ', ''))
    return parser.parse_expression()
